import sys

class Node:
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

def main():
    input = sys.stdin.read().split()
    ptr = 0
    n = int(input[ptr])
    ptr += 1
    head = None
    tail = None
    for _ in range(n):
        cmd = input[ptr]
        ptr += 1
        if cmd == 'insert':
            x = int(input[ptr])
            ptr += 1
            new_node = Node(x)
            if head is None:
                head = new_node
                tail = new_node
            else:
                new_node.next = head
                head.prev = new_node
                head = new_node
        elif cmd == 'delete':
            x = int(input[ptr])
            ptr += 1
            current = head
            while current is not None:
                if current.value == x:
                    if current.prev is not None:
                        current.prev.next = current.next
                    else:
                        head = current.next
                    if current.next is not None:
                        current.next.prev = current.prev
                    else:
                        tail = current.prev
                    break
                current = current.next
        elif cmd == 'deleteFirst':
            if head is not None:
                if head.next is None:
                    head = None
                    tail = None
                else:
                    head = head.next
                    head.prev = None
        elif cmd == 'deleteLast':
            if tail is not None:
                if tail.prev is None:
                    head = None
                    tail = None
                else:
                    tail = tail.prev
                    tail.next = None
    elements = []
    current = head
    while current is not None:
        elements.append(str(current.value))
        current = current.next
    print(' '.join(elements))

